tests.code:
if (!/^\s*<!DOCTYPE html>/i.test(code)) throw new Error("Start with <!DOCTYPE html>.");
if (!/<html\s+lang=["']en["']\s*>/i.test(code)) throw new Error("<html lang=\"en\"> is required.");
if (!/<head[\s\S]*<meta\s+charset=["']UTF-8["'][\s\S]*<\/head>/i.test(code)) throw new Error("The head needs <meta charset=\"UTF-8\">.");
if (!/<title>[\s\S]*?<\/title>/i.test(code)) throw new Error("Add a <title> in the head.");
if (!/<body[\s\S]*<\/body>/i.test(code)) throw new Error("All visible content goes in the <body>.");

const m = code.match(/<h1\s*>([\s\S]*?)<\/h1\s*>/i);
if (!m || m[1].trim() !== "My Weekend Project") {
  throw new Error("The h1 text must be exactly: My Weekend Project");
}

const h2pos = code.search(/<h2/i) === -1 ? code.length : code.search(/<h2/i);
const before = code.slice(0, h2pos).match(/<p>[\s\S]*?<\/p>/gi) ?? [];
if (before.length < 2) {
  throw new Error("Write two <p> paragraphs of story before the 'What I learned' section.");
}

if (!/<h2\s*>What I learned<\/h2\s*>/i.test(code)) {
  throw new Error("Add the section heading exactly: <h2>What I learned</h2>");
}
const h2End = code.search(/<\/h2>/i) + 5;
if (!/<p>[\s\S]*?<\/p>/i.test(code.slice(h2End))) {
  throw new Error("The 'What I learned' section needs at least one paragraph after the heading.");
}
